//! MVP timers (More… > MVP Timers): when a boss monster dies in sight, the time it can come
//! back. The spawns and their delays are the server's own (mvptimes_db.rs, generated by
//! tools/mvptimes from its NPC scripts): it returns between the base delay and the base plus
//! the variance after it died. The window lists each with that window counting down; once
//! it opens, chat says so. Deaths are kept in settings.toml (unix times), so the timers
//! carry over between sessions; one is dropped an hour after its window has closed.

use egui::{Color32, RichText};
use serde::{Deserialize, Serialize};

use crate::mvptimes_db::{BOSS_SPAWN_DELAY, SPAWNS};

/// A boss seen dying.
#[derive(Serialize, Deserialize, Clone, Debug, PartialEq)]
pub struct Death {
    pub map: String,
    pub mob: u16,
    pub name: String,
    /// Unix seconds.
    pub died: i64,
    /// Chat has said its window opened.
    #[serde(default)]
    pub told: bool,
}

/// How long a timer stays after its window has closed (it is surely up by then).
const KEEP_AFTER: i64 = 3600;

/// When a boss of `mob` on `map` can be back after dying: (earliest, latest) seconds.
pub fn respawn(map: &str, mob: u16) -> Option<(i64, i64)> {
    let &(_, _, base, extra) = SPAWNS.iter().find(|s| s.0 == map && s.1 == mob)?;
    let scale = |ms: u32| (ms as i64 * BOSS_SPAWN_DELAY as i64 / 100 / 1000).max(1);
    Some((scale(base), scale(base + extra)))
}

/// Where a timer stands at `now`.
#[derive(Debug, PartialEq)]
pub enum State {
    /// Seconds until it can be back.
    Waiting(i64),
    /// It can be back now; seconds until it surely is.
    Window(i64),
    /// Surely back.
    Up,
}

pub fn state(d: &Death, now: i64) -> Option<State> {
    let (early, late) = respawn(&d.map, d.mob)?;
    let (from, to) = (d.died + early, d.died + late);
    Some(if now < from {
        State::Waiting(from - now)
    } else if now < to {
        State::Window(to - now)
    } else {
        State::Up
    })
}

/// "1:05:09" or "5:09".
pub fn clock(secs: i64) -> String {
    let s = secs.max(0);
    if s >= 3600 { format!("{}:{:02}:{:02}", s / 3600, s % 3600 / 60, s % 60) } else { format!("{}:{:02}", s / 60, s % 60) }
}

pub fn now_unix() -> i64 {
    std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map_or(0, |d| d.as_secs() as i64)
}

#[derive(Default)]
pub struct MvpTimers {
    pub open: bool,
}

impl MvpTimers {
    /// A unit died on `map`: a timer if it is a boss with a timed spawn there. True when
    /// `deaths` changed.
    pub fn died(deaths: &mut Vec<Death>, map: &str, mob: u16, name: &str, now: i64) -> bool {
        if respawn(map, mob).is_none() {
            return false;
        }
        // One timer per boss and map: the latest death.
        deaths.retain(|d| !(d.map == map && d.mob == mob));
        deaths.push(Death { map: map.to_string(), mob, name: name.to_string(), died: now, told: false });
        true
    }

    /// Timers whose window just opened (for chat) and old ones dropped. True when `deaths`
    /// changed.
    pub fn tick(deaths: &mut Vec<Death>, now: i64, mut say: impl FnMut(&Death)) -> bool {
        let mut changed = false;
        for d in deaths.iter_mut() {
            if !d.told && matches!(state(d, now), Some(State::Window(_) | State::Up)) {
                d.told = true;
                changed = true;
                say(d);
            }
        }
        let before = deaths.len();
        deaths.retain(|d| respawn(&d.map, d.mob).is_some_and(|(_, late)| now < d.died + late + KEEP_AFTER));
        changed || deaths.len() != before
    }

    /// The window. True when `deaths` changed (one was removed). `map_name` gives a map's
    /// display name.
    pub fn show(&mut self, ctx: &egui::Context, deaths: &mut Vec<Death>, map_name: &dyn Fn(&str) -> Option<String>) -> bool {
        if !self.open {
            return false;
        }
        let now = now_unix();
        let mut open = true;
        let mut remove = None;
        let gray = crate::classic::ink(Color32::GRAY);
        crate::classic::show(ctx, egui::Window::new("MVP Timers").open(&mut open).default_width(420.0), "MVP Timers", true, |ui| {
            if deaths.is_empty() {
                ui.label(RichText::new("No timers yet. When an MVP or boss dies where you can see it, its respawn time shows here.").color(gray));
                return;
            }
            let mut list: Vec<(usize, &Death, State)> = deaths.iter().enumerate().filter_map(|(i, d)| Some((i, d, state(d, now)?))).collect();
            // Soonest first.
            list.sort_by_key(|(_, _, s)| match s {
                State::Up => i64::MIN,
                State::Window(left) => -1_000_000 + *left,
                State::Waiting(left) => *left,
            });
            egui::Grid::new("mvp_timers").num_columns(4).striped(true).spacing([14.0, 4.0]).show(ui, |ui| {
                for h in ["Monster", "Map", "Respawn", ""] {
                    ui.label(RichText::new(h).color(gray));
                }
                ui.end_row();
                for (i, d, s) in list {
                    ui.label(RichText::new(&d.name).strong());
                    ui.label(map_name(&d.map).map_or_else(|| d.map.clone(), |n| format!("{n} ({})", d.map)));
                    let (text, color) = match s {
                        State::Waiting(left) => {
                            let span = respawn(&d.map, d.mob).map_or(0, |(e, l)| l - e);
                            (if span > 0 { format!("in {} to {}", clock(left), clock(left + span)) } else { format!("in {}", clock(left)) }, Color32::WHITE)
                        }
                        State::Window(left) => (format!("may be up now (surely in {})", clock(left)), Color32::from_rgb(255, 210, 90)),
                        State::Up => ("up".to_string(), Color32::from_rgb(140, 230, 140)),
                    };
                    ui.label(RichText::new(text).color(crate::classic::ink(color)));
                    if ui.small_button("×").on_hover_text("Remove this timer").clicked() {
                        remove = Some(i);
                    }
                    ui.end_row();
                }
            });
            ui.add_space(4.0);
            ui.label(RichText::new("Counted from the kills you saw; the server brings each back at a random time within its window.").size(11.0).color(gray));
        });
        self.open = open;
        if let Some(i) = remove {
            deaths.remove(i);
            return true;
        }
        false
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn baphomet_in_the_maze_comes_back_in_two_hours_and_up_to_ten_minutes() {
        assert_eq!(respawn("prt_maze03", 1039), Some((7200, 7800)));
        assert_eq!(respawn("prontera", 1039), None);
    }

    #[test]
    fn a_timer_waits_then_opens_once_then_goes() {
        let mut deaths = vec![];
        assert!(MvpTimers::died(&mut deaths, "prt_maze03", 1039, "Baphomet", 1000));
        assert!(!MvpTimers::died(&mut deaths, "prt_maze03", 1002, "Poring", 1000));
        assert_eq!(state(&deaths[0], 1000 + 60), Some(State::Waiting(7140)));
        let mut said = 0;
        assert!(!MvpTimers::tick(&mut deaths, 1000 + 60, |_| said += 1));
        assert!(MvpTimers::tick(&mut deaths, 1000 + 7300, |_| said += 1));
        assert_eq!(state(&deaths[0], 1000 + 7300), Some(State::Window(500)));
        assert!(!MvpTimers::tick(&mut deaths, 1000 + 7400, |_| said += 1));
        assert_eq!(said, 1);
        assert_eq!(state(&deaths[0], 1000 + 7900), Some(State::Up));
        // Killed again: one timer, from the new death.
        MvpTimers::died(&mut deaths, "prt_maze03", 1039, "Baphomet", 9000);
        assert_eq!(deaths.len(), 1);
        assert!(MvpTimers::tick(&mut deaths, 9000 + 7800 + KEEP_AFTER, |_| {}));
        assert!(deaths.is_empty());
        assert_eq!(clock(3909), "1:05:09");
        assert_eq!(clock(309), "5:09");
    }
}
